#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

using WordCount = std::pair<std::string, int>;

std::vector<WordCount> rankWordsByCount(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> counts;
    for (const std::string& word : words) {
        counts[word]++;
    }
    std::vector<WordCount> ranked(counts.begin(), counts.end());
    std::sort(ranked.begin(), ranked.end(), [](const WordCount& a, const WordCount& b) {
        if (a.second != b.second) {
            return a.second > b.second;
        }
        return a.first < b.first;
    });
    return ranked;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::string> words(n);
    for (int i = 0; i < n; i++) {
        std::cin >> words[i];
    }
    for (const WordCount& entry : rankWordsByCount(words)) {
        std::cout << entry.first << " " << entry.second << "\n";
    }
    return 0;
}

